validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const ids = new Set();
  for (const [id, name, , salary] of Employees) {
    if (id === null) return 'Every employee needs an employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice.`;
    if (name === null) return `Employee ${id} needs a name.`;
    if (salary === null) return `Employee ${id} needs a salary.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const names = ['Mila', 'Antonella', 'Emery', 'Kalel', 'Mikaela', 'Joziah', 'Ana', 'Bob'];
  // Small salaries sit on both sides of 30000, including the boundary itself.
  const smallSalaries = [21241, 28485, 29999, 30000, 30001, 31000, 50937];
  const count = small ? pick(9) : 2000, pool = small ? 10 : 2600;
  const Employees = [], used = new Set();
  while (Employees.length < count) {
    const id = 1 + pick(pool);
    if (used.has(id)) continue;
    used.add(id);
    // Managers come from a slightly wider id range, so some point at nobody (a manager who left).
    const manager = rand() < 0.25 ? null : 1 + pick(pool + (small ? 3 : 300));
    const salary = small ? smallSalaries[pick(smallSalaries.length)] : rand() < 0.02 ? 30000 : 10000 + pick(50000);
    Employees.push([id, names[pick(names.length)], manager, salary]);
  }
  return [{ Employees }];
}
